def _backfill() -> None:
    """Give every existing user a personal workspace and attach their projects to it."""
    import uuid
    from datetime import datetime, timezone
    conn = op.get_bind()
    now = datetime.now(timezone.utc)
    users = conn.execute(sa.text("SELECT id, name FROM users")).fetchall()
    for uid_, name in users:
        wid = uuid.uuid4().hex
        first = (name or "My").split(" ")[0]
        conn.execute(sa.text("INSERT INTO workspaces (id, name, owner_id, personal, created_at) VALUES (:i, :n, :o, :p, :c)"),
                     {"i": wid, "n": f"{first}'s workspace", "o": uid_, "p": True, "c": now})
        conn.execute(sa.text("INSERT INTO workspace_members (workspace_id, user_id, role, created_at) VALUES (:w, :u, 'OWNER', :c)"), {"w": wid, "u": uid_, "c": now})
        conn.execute(sa.text("UPDATE projects SET workspace_id = :w WHERE owner_id = :u AND workspace_id IS NULL"), {"w": wid, "u": uid_})
    conn.execute(sa.text("UPDATE dataset_versions SET finalized_at = created_at WHERE finalized_at IS NULL"))
    # 'uncertain' was the old name of an escalated review: it stays open for a senior reviewer
    conn.execute(sa.text("UPDATE reviews SET status = 'escalated' WHERE status = 'uncertain'"))
    conn.execute(sa.text("UPDATE predictions SET review_status = 'escalated' WHERE review_status = 'uncertain'"))


